// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address _owner) public {
        vm.assume(caller != address(0) && _owner != address(0));
        vm.prank(caller);
        // Try to call setOwner; it will revert if caller is not the current owner.
        // Initially owner is address(this) (deployer), so we need to set caller to owner first.
        // But to test the general rule, we can change owner to caller via the original owner.
        // Actually, we can deploy a new C where we control the owner. Instead, let's use the constructor's owner.
        // For fuzzing, we'll first call setOwner as the original owner to make caller the owner,
        // then call again with _owner and check that owner becomes _owner.
        vm.prank(c.owner());
        c.setOwner(caller);
        vm.prank(caller);
        c.setOwner(_owner);
        assertTrue(c.owner() == _owner);
    }
}

